ALTER TABLE "data_manager"."configuration_fence" DROP CONSTRAINT "configuration_fence_state";--> statement-breakpoint
ALTER TABLE "data_manager"."configuration_fence" ADD CONSTRAINT "configuration_fence_state" CHECK (("data_manager"."configuration_fence"."state" = 'prepared' AND "data_manager"."configuration_fence"."outcome" IS NULL AND "data_manager"."configuration_fence"."settled_at" IS NULL) OR ("data_manager"."configuration_fence"."state" = 'settled' AND "data_manager"."configuration_fence"."outcome" IN ('applied','unused','contained') AND "data_manager"."configuration_fence"."settled_at" IS NOT NULL) OR ("data_manager"."configuration_fence"."state" = 'refused' AND "data_manager"."configuration_fence"."outcome" IS NULL AND "data_manager"."configuration_fence"."settled_at" IS NOT NULL));